class WorkspaceClient(ManagementClient):
    """Cbox ID — Workspace Management API.

    The **workspace plane** — the customer's own Cbox account, above every environment it owns. Manage the
    workspace, its **projects** (IdP products, each a billing anchor) and their
    environments, its team, and its keys with a workspace key.

    ``base_url`` defaults to ``https://api.cboxid.com``.
    """

    _plane = "workspace"
    _default_base_url = "https://api.cboxid.com"

    def _bind(self, core: ManagementTransport) -> None:
        self.action_approvals = ActionApprovalsMethods(core)
        self.environments = EnvironmentsMethods(core)
        self.keys = KeysMethods(core)
        self.projects = ProjectsMethods(core)
        self.team = TeamMethods(core)
        self.workspace = WorkspaceMethods(core)
